local M = {}
local managed_tab = require('codeit.ui.managed_tab')
local pending = {}
local last_input
local pumping, timer_pending = false, false
local idle_ms, poll_ms = 1000, 250

vim.on_key(function(_, typed)
  -- Approval navigation and decisions must not postpone the next queued prompt.
  if vim.b.codeit_approval then return end
  -- Ignore keys generated by mappings or renderer commands, rather than user input.
  if typed == nil or typed ~= '' then last_input = vim.uv.hrtime() end
end, vim.api.nvim_create_namespace('codeit_approval_idle'))

local function available(entry)
  local tab = entry.tab
  if entry.managed then tab = managed_tab.tab() end
  if not tab or vim.api.nvim_get_current_tabpage() ~= tab then return false end
  local mode = vim.api.nvim_get_mode()
  if mode.mode ~= 'n' or mode.blocking or vim.fn.pumvisible() ~= 0 then return false end
  if last_input and (vim.uv.hrtime() - last_input) / 1e6 < idle_ms then return false end
  for _, win in ipairs(vim.api.nvim_tabpage_list_wins(tab)) do
    local config = vim.api.nvim_win_get_config(win)
    local buf = vim.api.nvim_win_get_buf(win)
    if config.relative ~= '' and not config.hide and not vim.b[buf].codeit_notification
      and vim.api.nvim_buf_get_name(buf) ~= 'codeit://chat' then
      return false
    end
  end
  return true
end

local function pump()
  if pumping then return end
  pumping = true
  while #pending > 0 do
    local entry = pending[1]
    -- Liveness checks can resolve the workspace from the current tab's cwd.
    if not available(entry) then
      if not entry.approval_round.notified then
        entry.approval_round.notified = true
        vim.notify('Approval required', vim.log.levels.INFO, { title = 'Codeit' })
      end
      break
    elseif entry.active and not entry.active() then
      table.remove(pending, 1)
    else
      table.remove(pending, 1)
      local ok, err = pcall(entry.show)
      if not ok then
        if entry.on_error then entry.on_error(err)
        else vim.notify('codeit: could not show approval prompt: ' .. tostring(err), vim.log.levels.ERROR) end
      end
    end
  end
  pumping = false
  if #pending > 0 and not timer_pending then
    timer_pending = true
    vim.defer_fn(function()
      timer_pending = false
      pump()
    end, poll_ms)
  end
end

--- Defer approvals until the user is idle, in their chat tab, with no other popup open.
--- Returns a function that removes this entry if it is still queued.
function M.enqueue(show, active, on_error, approval_round)
  local entry = {
    show = show, active = active, on_error = on_error,
    approval_round = approval_round or {},
    managed = managed_tab.tab() ~= nil, tab = vim.api.nvim_get_current_tabpage(),
  }
  pending[#pending + 1] = entry
  pump()
  return function()
    for i, queued in ipairs(pending) do
      if queued == entry then table.remove(pending, i); break end
    end
  end
end

return M
